/** The day's 100 AI people. Same cast for every prompt that day, so each person is consistent. */
export function buildAiCast(date: string, config: GhostConfig = GHOST_CONFIG): CastMember[] {
  const rng = seededRng(`ai-cast:${date}`);
  return castOf(config.aiGhosts, rng, config).map(({ ability, style }, i) => {
    const options = PERSONAS[ability];
    return { id: i + 1, ability, style, persona: options[Math.floor(rng() * options.length)]! };
  });
}

const pct = (x: number) => `${Math.round(x * 100)}%`;

export function ghostSystemPrompt(config: GhostConfig = GHOST_CONFIG): string {
  const a = config.abilities;
  return `You are helping to calibrate Oddle, a daily maths game.

How the game works: a player sees a prompt such as "Name a prime under 1,000". It has many correct whole-number answers. The player has 25 seconds to type one. A wrong number is rejected and they can try again until the time runs out. Any correct answer scores, but the fewer other people who gave the same answer, the more it scores. So the game needs a realistic picture of what real people type, including how often they pile onto the same numbers.

You will be given one prompt and a cast of people. Play each person honestly, as they would really behave with 25 seconds on a phone. Each has an ability level and a playing style.

Ability levels:
- ultra: can recall almost any correct answer, including obscure ones. Barely swayed by which numbers feel familiar. Runs out of time about ${pct(a.ultra.timeoutRate)} of the time; rarely types a wrong number first.
- pretty: knows the more familiar ${pct(a.pretty.reach)} or so of the answers. Runs out of time about ${pct(a.pretty.timeoutRate)} of the time; sometimes one wrong try first.
- average: knows only the most familiar ${pct(a.average.reach)} or so. Runs out of time about ${pct(a.average.timeoutRate)} of the time; often one wrong try first.
- weak: knows only the most familiar ${pct(a.weak.reach)} or so, mostly very small or familiar numbers. Runs out of time about ${pct(a.weak.timeoutRate)} of the time; one to three wrong tries.
- panicker: blurts the first thing that comes to mind, often the single most obvious answer. Runs out of time about ${pct(a.panicker.timeoutRate)} of the time; one to three wrong tries.

Playing styles:
- safe: picks from the top of what they know (for primes: 2, 3, 5, 7).
- mid: skips the first thing that comes to mind and picks something a bit further down.
- risk: deliberately reaches for the least obvious answer they know.
- showoff: tries to look clever, so goes for famous numbers like 1729, 42, 8128, 6174 or 37 if one fits, otherwise acts like a risk-taker.

For each person return:
- "attempts": every number they type, in order, including wrong ones. Wrong tries must really be wrong for the prompt.
- "final": the correct number they end up handing in, or -1 if they run out of time.

Be realistic about overlap: many people land on the same few numbers. Do not spread the answers out artificially. Return every person in the cast, each with their id, ability and style exactly as given.`;
}

export const GHOST_SCHEMA = {
  type: 'object',
  properties: {
    people: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          id: { type: 'integer' },
          ability: { type: 'string', enum: [...ABILITIES] },
          style: { type: 'string', enum: [...STYLES] },
          attempts: { type: 'array', items: { type: 'integer' } },
          final: { type: 'integer' },
        },
        required: ['id', 'ability', 'style', 'attempts', 'final'],
        additionalProperties: false,
      },
    },
  },
  required: ['people'],
  additionalProperties: false,
} as const;

export function buildGhostUserMessage(prompt: Prompt, cast: readonly CastMember[]): string {
  const people = cast.map((c) => `${c.id} | ${c.ability} | ${c.style} | ${c.persona}`).join('\n');
  return `Prompt: ${prompt.text}
Allowed range: ${prompt.min.toLocaleString('en-GB')} to ${prompt.max.toLocaleString('en-GB')} inclusive.

Cast (id | ability | style | who they are):
${people}`;
}

export interface AiReplyEntry {
  attempts: number[];
  final: number;
}

/** Read the model's reply: id → what they did. Null if it can't be understood at all. */
export function parseGhostReply(text: string): Map<number, AiReplyEntry> | null {
  let data: unknown;
  try {
    data = JSON.parse(text.replace(/^\s*```(?:json)?\s*|\s*```\s*$/g, ''));
  } catch {
    return null;
  }
  const people = (data as { people?: unknown } | null)?.people;
  if (!Array.isArray(people)) return null;
  const out = new Map<number, AiReplyEntry>();
  for (const item of people) {
    const { id, attempts, final } = (item ?? {}) as { id?: unknown; attempts?: unknown; final?: unknown };
    if (typeof id !== 'number' || typeof final !== 'number' || !Number.isSafeInteger(final)) continue;
    out.set(id, {
      final,
      attempts: Array.isArray(attempts) ? attempts.filter((x): x is number => Number.isSafeInteger(x)) : [],
    });
  }
  return out.size > 0 ? out : null;
}

export interface AiStats {
  /** The API reply was usable at all. */
  used: boolean;
  /** AI ghosts who handed in a valid answer. */
  answered: number;
  /** AI ghosts who said they ran out of time. */
  timedOut: number;
  /** AI ghosts whose final answer was invalid: counted as time-outs. */
  invalid: number;
  /** Cast members missing from the reply: replaced with rule-based ghosts. */
  missing: number;
}

/**
 * The full set of ghosts for one prompt: 1,000 rule-based plus 100 AI, or
 * 1,100 rule-based if the AI reply is unusable.
 */
export function assemblePromptGhosts(
  prompt: Prompt,
  position: number,
  cast: readonly CastMember[],
  reply: Map<number, AiReplyEntry> | null,
  rng: Rng,
  ctx: GhostContext,
): { ghosts: GhostAnswer[]; stats: AiStats } {
  const config = ctx.config ?? GHOST_CONFIG;
  const stats: AiStats = { used: reply !== null, answered: 0, timedOut: 0, invalid: 0, missing: 0 };
  const ruleCount = config.ruleGhosts + (reply ? 0 : cast.length);
  const ghosts: GhostAnswer[] = generateRuleGhosts(prompt, ruleCount, rng, ctx).map((g) => ({
    position,
    value: g.value,
    ability: g.ability,
    style: g.style,
    source: 'rules',
  }));
  if (!reply) return { ghosts, stats };

  for (const member of cast) {
    const entry = reply.get(member.id);
    if (!entry) {
      stats.missing++;
      const g = playGhost(prompt, member.ability, member.style, rng, ctx);
      ghosts.push({ position, value: g.value, ability: member.ability, style: member.style, source: 'rules' });
      continue;
    }
    let value: number | null = null;
    if (entry.final === -1) stats.timedOut++;
    else if (isValidAnswer(prompt, entry.final)) {
      value = entry.final;
      stats.answered++;
    } else stats.invalid++;
    ghosts.push({ position, value, ability: member.ability, style: member.style, source: 'ai' });
  }
  return { ghosts, stats };
}
